-- Optional reference SQL for the CivicConnect PostgreSQL database.
-- The application normally creates the schema through EF Core EnsureCreated().

CREATE TABLE IF NOT EXISTS "Users" (
    "UserId" integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "Name" varchar(100) NOT NULL,
    "Email" varchar(200) NOT NULL,
    "Role" varchar(30) NOT NULL,
    "IsActive" boolean NOT NULL DEFAULT TRUE
);

CREATE TABLE IF NOT EXISTS "ServiceRequests" (
    "RequestId" integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "RequesterId" integer NOT NULL,
    "Category" varchar(100) NOT NULL,
    "Title" varchar(100) NOT NULL,
    "Description" varchar(1000) NOT NULL,
    "CurrentStatus" varchar(30) NOT NULL,
    "CreatedAt" timestamp with time zone NOT NULL,
    "UpdatedAt" timestamp with time zone NOT NULL,
    "AssignedStaffId" integer NULL,
    CONSTRAINT "FK_ServiceRequests_Requester"
        FOREIGN KEY ("RequesterId") REFERENCES "Users" ("UserId")
);
